window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-b26f920c263f2e68"]={"versions": [{"id": "FIG-b26f920c263f2e68", "releases": ["R4.3.1", "R18-10_R4.4.0_R1.5.0", "R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Bitbelegungsdiagramm / Protokoll-Header-Format für das SOME/IP-Transportprotokoll (SOME/IP-TP). Die Abbildung spezifiziert die Einbettung des TP-Flags innerhalb des Felds <code>Message Type</code> (8 Bit) des standardisierten SOME/IP-Headers.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Message Type</strong>: 8-Bit-Feld innerhalb des SOME/IP-Headers.\n</li><li><strong>bit offset</strong>: Bitpositionen 16 bis 23 (Big-Endian-Bitnummerierung innerhalb des SOME/IP-Header-Worts).\n</li><li><strong>TP-Flag</strong>: An Bit-Offset 18 verortetes Ein-Bit-Feld (Farbhervorhebung in Orange/Beige), Wertebereich <code>0/1</code>.\n</li><li><strong>ignore</strong>: Bit-Offsets 16, 17 sowie 19 bis 23 (Wertebelegung <code>x</code>), im Kontext des TP-Flags als irrelevant bzw. separat definierte Bits des <code>Message Type</code> dargestellt.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Datenstrukturformat. Das Bit an Position 18 signalisiert bei SOME/IP-Nachrichten, ob ein SOME/IP-TP-Header folgt (Wert <code>1</code>) oder ob es sich um eine reguläre, nicht segmentierte SOME/IP-Nachricht handelt (Wert <code>0</code>). Die übrigen Bits des <code>Message Type</code> werden bei der Auswertung des TP-Flags ignoriert.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Bitdefinition für Sender und Empfänger:</p>\n<ul class=\"fig-list\"><li>Ein Sender muss Bit-Offset 18 auf <code>1</code> setzen, wenn SOME/IP-Nachrichtensegmentierung via SOME/IP-TP genutzt wird.\n</li><li>Ein Empfänger prüft Bit 18 des Feldes <code>Message Type</code>, um zwischen regulären SOME/IP-Payloads und segmentierten TP-Nachrichten mit nachfolgendem TP-Zusatzheader zu unterscheiden.\n</li></ul>"}, {"id": "FIG-a33b89d39979d49b", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Bitbelegungsdiagramm / Protokoll-Header-Format für das SOME/IP-Transportprotokoll (SOME/IP-TP). Die Abbildung spezifiziert die Einbettung des TP-Flags innerhalb des Felds <code>Message Type</code> (8 Bit) des standardisierten SOME/IP-Headers.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Message Type</strong>: 8-Bit-Feld innerhalb des SOME/IP-Headers.\n</li><li><strong>bit offset</strong>: Bitpositionen 16 bis 23 (Big-Endian-Bitnummerierung innerhalb des SOME/IP-Header-Worts).\n</li><li><strong>TP-Flag</strong>: An Bit-Offset 18 verortetes Ein-Bit-Feld (Farbhervorhebung in Orange/Beige), Wertebereich <code>0/1</code>.\n</li><li><strong>ignore</strong>: Bit-Offsets 16, 17 sowie 19 bis 23 (Wertebelegung <code>x</code>), im Kontext des TP-Flags als irrelevant bzw. separat definierte Bits des <code>Message Type</code> dargestellt.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Datenstrukturformat. Das Bit an Position 18 signalisiert bei SOME/IP-Nachrichten, ob ein SOME/IP-TP-Header folgt (Wert <code>1</code>) oder ob es sich um eine reguläre, nicht segmentierte SOME/IP-Nachricht handelt (Wert <code>0</code>). Die übrigen Bits des <code>Message Type</code> werden bei der Auswertung des TP-Flags ignoriert.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Bitdefinition für Sender und Empfänger:</p>\n<ul class=\"fig-list\"><li>Ein Sender muss Bit-Offset 18 auf <code>1</code> setzen, wenn SOME/IP-Nachrichtensegmentierung via SOME/IP-TP genutzt wird.\n</li><li>Ein Empfänger prüft Bit 18 des Feldes <code>Message Type</code>, um zwischen regulären SOME/IP-Payloads und segmentierten TP-Nachrichten mit nachfolgendem TP-Zusatzheader zu unterscheiden.\n</li></ul>"}], "trans": [{"from": "FIG-b26f920c263f2e68", "to": "FIG-a33b89d39979d49b", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
